package dev.sablelife.testing;

import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
import com.simibubi.create.content.redstone.link.*;
import net.createmod.catnip.data.Couple;
import java.util.*;

@GameTestHolder("sablelife_signal_buffer_tests") @PrefixGameTestTemplate(false)
public final class SignalBufferGameTests {
 record Rig(HeartBlockEntity core,VirtualModule m){
  void input(int n){core.wireless().programOutputs("buffer_input",n==0?Map.of():Map.of(0,n));core.modules().events().tick(core);}
  int output(){return core.wireless().output(1);}
  int face(){var a=m.anchors().getFirst();return ModuleSignals.signal((net.minecraft.server.level.ServerLevel)core.getLevel(),a.position(a.body(core)).relative(a.face()),a.face());}
 }
 static Rig fixture(GameTestHelper h,int kind){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,50,4));l.setBlockAndUpdate(p,(kind==1?SableLife.SURVIVAL_LIFE_CORE.get():kind==2?SableLife.REDSTONE_CORE.get():SableLife.HEART.get()).defaultBlockState());l.setBlockAndUpdate(p.north(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.north()),new BoundingBox3i(p.getX(),p.getY(),p.getZ()-1,p.getX(),p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());var hover=c.modules().add("hover_anchor");hover.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));for(int i=0;i<2;i++){c.wireless().add();c.wireless().channel(i).set(6,3);}var m=c.modules().add("wireless_redstone");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos().north(),Direction.EAST)));m.edit("redstoneFaces",1,"");m.edit("redstoneStrengthMode",1,"");m.edit("trigger",2,"");m.edit("channel",1,"");m.edit("redstoneChannel",2,"");m.edit("redstoneBufferTime",4,"");var author=TestActors.creative(l);if(kind==1)c.depositSurvivalTokens(author,new ItemStack(Items.DIAMOND,64));c.tryActivate(author);h.assertTrue(c.operational(),"Fixture core not active");return new Rig(c,m);}
 static final class Link implements IRedstoneLinkable {
  final BlockPos pos;final Couple<RedstoneLinkNetworkHandler.Frequency> key;int rx;
  Link(BlockPos pos){this.pos=pos;key=Couple.create(RedstoneLinkNetworkHandler.Frequency.of(new ItemStack(Items.HONEYCOMB)),RedstoneLinkNetworkHandler.Frequency.of(new ItemStack(Items.CACTUS)));}
  public int getTransmittedStrength(){return 0;}public void setReceivedStrength(int n){rx=n;}public boolean isListening(){return true;}public boolean isAlive(){return true;}public Couple<RedstoneLinkNetworkHandler.Frequency> getNetworkKey(){return key;}public BlockPos getLocation(){return pos;}
 }
 @GameTest(template="combat",batch="buffer_three_outputs",timeoutTicks=35)
 public static void HoldRetainsLastAnalogStrengthAtAllDestinations(GameTestHelper h){var r=fixture(h,0);var c=r.core;var link=new Link(c.getBlockPos());r.m.redBlue(false,new ItemStack(Items.HONEYCOMB),h.getLevel().registryAccess());r.m.redBlue(true,new ItemStack(Items.CACTUS),h.getLevel().registryAccess());com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.addToNetwork(h.getLevel(),link);r.input(9);h.assertTrue(r.output()==9&&r.face()==9&&link.rx==9,"Initial destinations differ");h.runAfterDelay(10,()->{r.input(3);r.input(0);h.assertTrue(r.output()==3&&r.face()==3&&link.rx==3,"Buffer lost last analog value");});h.runAfterDelay(13,()->{c.modules().events().tick(c);h.assertTrue(r.output()==3&&r.face()==3&&link.rx==3,"Off delay ended too early");});h.runAfterDelay(15,()->{try{c.modules().events().tick(c);h.assertTrue(r.output()==0&&r.face()==0&&link.rx==0,"Buffer did not expire at all destinations");h.succeed();}finally{com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.removeFromNetwork(h.getLevel(),link);c.modules().events().clear();}});}
 @GameTest(template="combat",batch="buffer_retrigger",timeoutTicks=25)
 public static void NewPowerReplacesTailAndStartsANewOffDelay(GameTestHelper h){var r=fixture(h,0);r.input(9);r.input(0);h.runAfterDelay(2,()->{r.input(4);h.assertTrue(r.output()==4,"Old strength masked new input");r.input(0);});h.runAfterDelay(5,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==4,"Old deadline cut new buffer short");});h.runAfterDelay(7,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"New buffer did not end");h.succeed();});}
 @GameTest(template="combat",batch="buffer_pulse",timeoutTicks=25)
 public static void BufferStartsAfterCompletePulseEnds(GameTestHelper h){var r=fixture(h,0);r.m.edit("redstoneMode",1,"");r.m.edit("redstonePulse",2,"");r.input(6);r.input(0);h.runAfterDelay(2,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==6,"No tail after pulse");});h.runAfterDelay(5,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==6,"Buffer incorrectly started on input fall");});h.runAfterDelay(7,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Pulse plus buffer remained active");h.succeed();});}
 @GameTest(template="combat",batch="buffer_ramp",timeoutTicks=25)
 public static void RampKeepsFinalStrengthAfterTriggerEnds(GameTestHelper h){var r=fixture(h,0);r.m.edit("redstoneStrengthMode",2,"");r.m.edit("redstoneRampStart",3,"");r.m.edit("redstoneRampEnd",11,"");r.m.edit("redstoneRampTime",4,"");r.input(7);h.assertTrue(r.output()==3,"Ramp starting value changed");h.runAfterDelay(4,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==11,"Ramp endpoint wrong");r.input(0);});h.runAfterDelay(7,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==11,"Ramp tail lost endpoint");});h.runAfterDelay(9,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Ramp buffer did not end");r.input(7);h.assertTrue(r.output()==3,"New ramp did not replace old tail");h.succeed();});}
 @GameTest(template="combat",batch="buffer_inverse",timeoutTicks=25)
 public static void BufferUsesFinalInvertedOutput(GameTestHelper h){var r=fixture(h,0);r.m.edit("redstoneInvert",1,"");r.input(7);h.assertTrue(r.output()==8,"Inverse changed");r.input(0);h.assertTrue(r.output()==15,"Inverse idle high changed");r.input(15);h.assertTrue(r.output()==15,"Final falling output was not buffered");h.runAfterDelay(5,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Inverted low did not begin after buffer");h.succeed();});}
 @GameTest(template="combat",batch="buffer_cleanup")
 public static void DisableMasterReleaseAndRuntimeClearCancelPendingBuffers(GameTestHelper h){var r=fixture(h,0);r.m.edit("redstoneBufferTime",100,"");r.input(8);r.input(0);h.assertTrue(r.output()==8,"No pending buffer");r.m.edit("enabled",0,"");r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0&&r.face()==0,"Disable waited for buffer");r.m.edit("enabled",1,"");r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Re-enable restored stale tail");r.input(7);r.input(0);r.core.wireless().master(false);r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0&&r.face()==0,"Master off retained buffer");r.core.wireless().master(true);r.input(5);r.input(0);r.core.modules().clearRuntime();h.assertTrue(r.output()==0&&r.face()==0,"Runtime clear retained buffer");r.input(3);r.input(0);r.core.resetForCreative(TestActors.creative(h.getLevel()));h.assertTrue(r.output()==0&&r.face()==0,"Release retained buffer");h.succeed();}
 @GameTest(template="combat",batch="buffer_core_variants")
 public static void OrdinarySurvivalAndRedstoneCoreHaveIndependentBuffers(GameTestHelper h){for(int kind=0;kind<3;kind++){var r=fixture(h,kind);r.input(4+kind);r.input(0);h.assertTrue(r.output()==4+kind,"Core variant did not buffer: "+kind);if(kind==2)r.core.resetForCreative(TestActors.creative(h.getLevel()));else r.core.forceDeath();r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0&&r.face()==0,"Death or control-core release retained output: "+kind);}h.succeed();}
 @GameTest(template="combat",batch="buffer_invalid_unload")
 public static void InvalidMarksAndUnloadClearTailWithoutRestoringIt(GameTestHelper h){var r=fixture(h,0);r.input(8);r.input(0);var anchor=r.m.anchors().getFirst();r.m.invalidate();r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0&&r.face()==0,"Invalid module retained tail");r.m.anchors(List.of(anchor));r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Remark restored old tail");r.input(6);r.input(0);r.core.onChunkUnloaded();h.assertTrue(r.output()==0&&r.face()==0,"Unload retained output");h.succeed();}
 @GameTest(template="combat",batch="buffer_edit_cancel")
 public static void ChangingOrDisablingBufferClearsPendingTail(GameTestHelper h){var r=fixture(h,0);r.input(8);r.input(0);r.m.edit("redstoneBufferTime",20,"");r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0,"Duration edit kept old pending tail");r.input(4);r.input(0);r.m.edit("redstoneBufferTime",0,"");r.core.modules().events().tick(r.core);h.assertTrue(r.output()==0&&r.face()==0,"Buffer Off retained tail");h.succeed();}
 @GameTest(template="combat",batch="buffer_merge",timeoutTicks=25)
 public static void OtherPublishersRemainIndependentAndStrongestWins(GameTestHelper h){var r=fixture(h,0);var b=r.core.modules().add("wireless_redstone");b.edit("trigger",2,"");b.edit("channel",1,"");b.edit("redstonePower",12,"");b.edit("redstoneChannel",2,"");r.input(7);h.assertTrue(r.output()==12,"Strongest producer did not win");r.input(0);h.assertTrue(r.output()==7,"Zero-buffer producer or old strength leaked into tail");r.core.wireless().programOutputs("independent",Map.of(1,13));h.runAfterDelay(5,()->{r.core.modules().events().tick(r.core);h.assertTrue(r.output()==13,"Buffer expiry erased independent producer");r.core.wireless().programOutputs("independent",Map.of());h.assertTrue(r.output()==0,"Expired buffer revived");h.succeed();});}
 @GameTest(template="combat",batch="buffer_codec")
 public static void DefaultPresetCodecPermissionsAndNumericLimits(GameTestHelper h){var fresh=new VirtualModule("wireless_redstone");h.assertTrue(fresh.value("redstoneBufferTime")==0&&fresh.value("redstoneMode")==0,"Old defaults changed");fresh.edit("redstoneBufferTime",12000,"");var preset=ModulePreset.create(fresh.save());h.assertTrue(preset.value("redstoneBufferTime")==12000,"Preset lost buffer");var legacy=fresh.save();legacy.getCompound("Settings").remove("redstoneBufferTime");h.assertTrue(VirtualModule.load(legacy).value("redstoneBufferTime")==0,"Old data gained buffering");var r=fixture(h,0);r.core.resetForCreative(TestActors.creative(h.getLevel()));var author=TestActors.creative(h.getLevel());author.setPos(ModuleArena.corePosition(r.core));var menu=new HeartDashboardMenu(8,author.getInventory(),r.core);var action=new ModuleNetworking.Action(8,r.core.modules().revision(),r.m.id(),"edit","redstoneBufferTime",12000,"");var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ModuleNetworking.Action.CODEC.encode(buf,action);h.assertTrue(ModuleNetworking.Action.CODEC.decode(buf).equals(action),"Buffer action codec mismatch");}finally{buf.release();}h.assertTrue(menu.action(author,action.revision(),r.m.id(),"edit",action.key(),12000,"")&&r.m.value(action.key())==12000,"Menu maximum not delivered");h.assertTrue(!menu.action(author,action.revision(),r.m.id(),"edit",action.key(),0,""),"Stale request accepted");var denied=TestActors.creative(h.getLevel());denied.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);denied.setPos(author.position());h.assertTrue(!menu.action(denied,r.core.modules().revision(),r.m.id(),"edit",action.key(),0,""),"Unauthorized buffer edit");r.m.edit(action.key(),12001,"");h.assertTrue(r.m.value(action.key())==12000,"Upper bound bypassed");r.m.edit(action.key(),-1,"");h.assertTrue(r.m.value(action.key())==0&&!r.m.edit(action.key(),Double.NaN,"")&&!r.m.edit(action.key(),Double.POSITIVE_INFINITY,""),"Invalid duration accepted");h.assertTrue(dev.sablelife.client.NumericWheelSteps.module("wireless_redstone",action.key(),20,0)==.05,"Wrong wheel precision");h.succeed();}
}
